/* Plural endings, longest first. Spanish pluralises predictably enough
   that one rule saves a second entry for every noun in the table. */
const FILLER = new Set(["de", "del", "la", "el", "los", "las", "un", "una", "para", "con", "y"]);

/**
 * A shopper's query, in the language the retailer speaks.
 *
 * Returns { query, translated, changed } — `query` is what to search
 * with, and `translated` is true when anything was actually recognised,
 * so a caller can tell the shopper what we searched for.
 */
function carouselDiscountPct(it){
  const price = Number(it && (it.price ?? it.effectivePrice ?? it.currentPrice ?? it.salePrice));
  const original = Number(it && (it.regularPrice ?? it.wasPrice ?? it.was_price ?? it.originalPrice));
  if (!Number.isFinite(price) || !Number.isFinite(original) || price <= 0 || original <= price) return 0;
  return Math.round((1 - price / original) * 100);
}
const CAROUSEL_MIN_DISCOUNT_PCT = 5;
const SHOE_DEFAULT_RETAILERS = new Set(['footlocker']);
const CATALOG_SEARCH_LIMIT = 200;
/* Fewer than this many full-token matches is "thin", and thin is what
   makes the live offer the loudest thing on the page. */
const CATALOG_THIN_EXACT = 3;

/* ACCENTS ARE FOLDED, NOT SPLIT ON. `[a-z0-9]+` treats "ú" as a
   separator, so "búscame" tokenised to ["b","scame"] -- and a
   one-character token then prefix-matched every word in the catalogue
   beginning with b. Measured on "búscame unos tenis Nike": 2,144
   partial matches, with televisions and a gift box ranked as answers to
   a question about trainers. Folding the accent first gives "buscame",
   one token, matching nothing, which is the truth about it.

   The catalogue's titles are English and the shopper writes Spanish, so
   this has to happen on BOTH sides of the comparison -- hence
   catalogWordsOf() runs the same function over the title. */
function searchTokens(raw){
  return String(raw || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .match(/[a-z0-9]+/g) || [];
}

/* Title and brand are the searchable surface. Not the description: the
   catalogues do not carry one for every store, and a field that exists
   for some products would silently rank those above the rest. */
function catalogWordsOf(item){
  return new Set(searchTokens((item?.title || '') + ' ' + (item?.brand || '')));
}

/* PREFIXES IN BOTH DIRECTIONS, AND WHY THE SECOND ONE IS NEEDED.

   Matching a word that merely STARTS WITH the token covers "vitamin"
   finding "vitamins". It does not cover the reverse, and the reverse is
   what actually happens here: translateQuery("Vitamina D3") returns
   "vitamins D3" -- the Spanish layer pluralises -- while every title in
   the catalogue says "Vitamin D3". Measured before this: 0 full matches
   for one of the four queries the brief names, on 5 products that are
   plainly the right answer.

   The 4-character floor on the stem is what keeps this from becoming
   substring matching again: "a", "de" and "3" must never match a word
   just because it starts with them. */
/* A FLOOR ON BOTH DIRECTIONS OF THE PREFIX RULE, and the forward one
   needed it as badly as the reverse. A token of one or two characters
   that is allowed to match any longer word starting with it is not a
   search, it is a wildcard: "b" matched a sixth of the catalogue. An
   EXACT word match stays unrestricted, so "tv", "d3" and "5k" still
   work -- it is only the prefix shortcut that needs the shopper to have
   typed enough to mean something. */
const CATALOG_MIN_PREFIX = 3;

